import itertools, json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
tr=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(tr[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,s):
 pos={j:p.index(j)+1 for j in jobs}
 if s=='rain':
  if pos['C']==5 or pos['A']==1:return None
  penalty=8*max(0,pos['E']-1)
 elif s=='road':
  if pos['B']==1 or pos['C']==2:return None
  penalty=5*max(0,pos['D']-3)
 else:
  if pos['D']==5 or pos['B']==5:return None
  penalty=5*max(0,pos['E']-2)
 return nominal(p)+penalty
valid=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
results=[]
for p in valid:
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
  if q.index('A')<q.index('D'):neighbors.append((q,1))
 best={}
 for s in ['rain','road','lift']:
  choices=[(incident(q,s)+ex,q) for q,ex in neighbors if incident(q,s) is not None]
  if not choices:break
  best[s]=min(choices)
 if len(best)==3:results.append((nominal(p)+max(c for c,q in best.values()),p,best))
results.sort()
score,p,best=results[0]
print(json.dumps({'roster':p,'score':score,'repairs':{s:q for s,(c,q) in best.items()},'repair_costs':{s:c for s,(c,q) in best.items()},'feasible_count':len(results),'next_score':min(r[0] for r in results if r[0]>score)}))
print('published nominal',nominal(p),'optimal ties',sum(r[0]==score for r in results))
# Independent cross-check: all valid final permutations filtered by Hamming distance 0 or 2.
check=[]
for p in valid:
 minima=[]
 for s in ['rain','road','lift']:
  costs=[]
  for q in valid:
   d=sum(a!=b for a,b in zip(p,q))
   if d not in (0,2):continue
   c=incident(q,s)
   if c is not None:costs.append(c+(d==2))
  if not costs:break
  minima.append(min(costs))
 if len(minima)==3:check.append((nominal(p)+max(minima),p))
assert sorted(check)==sorted((s,p) for s,p,b in results)
print('independent neighborhood check passed',len(check))

