import itertools,json
jobs='ABCDE';pub='EABDC'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
tr=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def distance(q):
 perm=[pub.index(j) for j in q];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;k=i
   while k not in seen:seen.add(k);k=perm[k]
 return 5-cycles
rows={d:[] for d in range(3)}
for t in itertools.permutations(jobs):
 q=''.join(t);d=distance(q)
 if d>2:continue
 if q.index('A')>q.index('D') or q[4]=='C' or q[0] in 'AE':continue
 nominal=sum(slot[j][i] for i,j in enumerate(q))+sum(tr[a][jobs.index(b)] for a,b in zip(q,q[1:]))
 cost=nominal+8*q.index('E')+d+(10 if d==2 else 0)
 rows[d].append((cost,q))
best=min(x for r in rows.values() for x in r)
# Independently verify distance classes by breadth-first pair exchanges.
dist={pub:0};front={pub}
for d in [1,2]:
 nxt=set()
 for p in front:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
   if q not in dist:nxt.add(q)
 for q in nxt:dist[q]=d
 front=nxt
for q,d in dist.items():assert distance(q)==d
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(r)[0] if r else None for d,r in rows.items()},'feasible_by_swaps':{str(d):len(r) for d,r in rows.items()}}))
print('classes',rows)

